messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: a low-poly 3D humanoid figure performs this exact cycle on a treadmill-style ground, side-on camera: stands still for 2 seconds, walks in place for 3 seconds (limbs swinging at walking pace), runs in place for 3 seconds (faster, larger limb swings, slight forward lean), then stands still again for 2 seconds. The 10-second cycle loops forever and must start immediately on load. Limb movement must clearly differ between walking and running. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Three.js Humanoid Cycle</title>
  <style>
    body { margin: 0; overflow: hidden; background: #1a1a2e; font-family: Arial, Helvetica, sans-serif; }
    canvas { display: block; }
    .info {
      position: absolute;
      bottom: 20px;
      left: 20px;
      color: #aaa;
      font-size: 14px;
      background: rgba(0,0,0,0.5);
      padding: 8px 12px;
      border-radius: 8px;
      pointer-events: none;
      z-index: 10;
    }
    .phase {
      position: absolute;
      top: 20px;
      left: 20px;
      color: #fff;
      font-size: 18px;
      background: rgba(0,0,0,0.6);
      padding: 6px 14px;
      border-radius: 20px;
      pointer-events: none;
      z-index: 10;
      letter-spacing: 1px;
    }
  </style>
</head>
<body>
  <div class="info">side-on view · low-poly humanoid · 10s loop</div>
  <div class="phase" id="phaseDisplay">standing</div>
  <script type="importmap">
    { "imports": { "three": "./three.module.js" } }
  </script>
  <script type="module">
    import * as THREE from './three.module.js';

    // --- Scene setup ---
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x1a1a2e);
    scene.fog = new THREE.Fog(0x1a1a2e, 20, 40);

    const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
    camera.position.set(6, 4, 8);
    camera.lookAt(0, 1.2, 0);

    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    document.body.appendChild(renderer.domElement);

    // --- Lighting ---
    const ambient = new THREE.HemisphereLight(0x404060, 0x202030, 1.0);
    scene.add(ambient);

    const dirLight = new THREE.DirectionalLight(0xffffff, 1.2);
    dirLight.position.set(5, 8, 6);
    dirLight.castShadow = true;
    dirLight.shadow.mapSize.width = 512;
    dirLight.shadow.mapSize.height = 512;
    dirLight.shadow.camera.near = 0.5;
    dirLight.shadow.camera.far = 20;
    dirLight.shadow.camera.left = -5;
    dirLight.shadow.camera.right = 5;
    dirLight.shadow.camera.top = 5;
    dirLight.shadow.camera.bottom = -5;
    scene.add(dirLight);

    const rimLight = new THREE.PointLight(0x4466aa, 0.6);
    rimLight.position.set(-3, 3, -2);
    scene.add(rimLight);

    // --- Ground / treadmill style ---
    const groundGeo = new THREE.BoxGeometry(8, 0.2, 3);
    const groundMat = new THREE.MeshStandardMaterial({ color: 0x2a2a3a, roughness: 0.7 });
    const ground = new THREE.Mesh(groundGeo, groundMat);
    ground.position.y = -0.1;
    ground.receiveShadow = true;
    scene.add(ground);

    // Treadmill belt lines
    const beltMat = new THREE.MeshStandardMaterial({ color: 0x4a4a5a, roughness: 0.5 });
    for (let i = -3; i <= 3; i += 1.5) {
      const bar = new THREE.Mesh(new THREE.BoxGeometry(0.15, 0.05, 2.6), beltMat);
      bar.position.set(i, 0.1, 0);
      bar.rotation.x = 0.1;
      bar.receiveShadow = true;
      scene.add(bar);
    }

    // Side rails
    const railMat = new THREE.MeshStandardMaterial({ color: 0x3a3a4a });
    const rail1 = new THREE.Mesh(new THREE.BoxGeometry(8, 0.3, 0.2), railMat);
    rail1.position.set(0, 0.35, -1.5);
    rail1.receiveShadow = true;
    scene.add(rail1);
    const rail2 = rail1.clone();
    rail2.position.set(0, 0.35, 1.5);
    scene.add(rail2);

    // --- Humanoid figure (low-poly) ---
    const humanoid = new THREE.Group();
    humanoid.position.y = 0.0;
    humanoid.castShadow = true;

    // Materials
    const skinMat = new THREE.MeshStandardMaterial({ color: 0x8a6e5a, roughness: 0.8 });
    const shirtMat = new THREE.MeshStandardMaterial({ color: 0x3a5a8a, roughness: 0.7 });
    const pantsMat = new THREE.MeshStandardMaterial({ color: 0x2a3a4a, roughness: 0.7 });
    const shoeMat = new THREE.MeshStandardMaterial({ color: 0x1a1a1a, roughness: 0.9 });
    const headMat = new THREE.MeshStandardMaterial({ color: 0x8a6e5a, roughness: 0.8 });

    // Torso (shirt)
    const torsoGeo = new THREE.BoxGeometry(0.8, 1.0, 0.4);
    const torso = new THREE.Mesh(torsoGeo, shirtMat);
    torso.position.y = 0.9;
    torso.castShadow = true;
    humanoid.add(torso);

    // Head
    const headGeo = new THREE.BoxGeometry(0.5, 0.5, 0.5);
    const head = new THREE.Mesh(headGeo, headMat);
    head.position.y = 1.6;
    head.castShadow = true;
    humanoid.add(head);

    // Hat / hair (simple cube)
    const hairMat = new THREE.MeshStandardMaterial({ color: 0x3a2a1a });
    const hair = new THREE.Mesh(new THREE.BoxGeometry(0.55, 0.2, 0.55), hairMat);
    hair.position.y = 1.85;
    hair.castShadow = true;
    humanoid.add(hair);

    // Arms (left and right) as groups with upper/lower segments
    // Left arm group
    const leftArmGroup = new THREE.Group();
    leftArmGroup.position.set(-0.5, 1.35, 0);
    const leftUpper = new THREE.Mesh(new THREE.BoxGeometry(0.2, 0.6, 0.2), skinMat);
    leftUpper.position.y = -0.3;
    leftUpper.castShadow = true;
    leftArmGroup.add(leftUpper);
    const leftLower = new THREE.Mesh(new THREE.BoxGeometry(0.18, 0.5, 0.18), skinMat);
    leftLower.position.y = -0.8;
    leftLower.castShadow = true;
    leftArmGroup.add(leftLower);
    humanoid.add(leftArmGroup);

    // Right arm group
    const rightArmGroup = new THREE.Group();
    rightArmGroup.position.set(0.5, 1.35, 0);
    const rightUpper = new THREE.Mesh(new THREE.BoxGeometry(0.2, 0.6, 0.2), skinMat);
    rightUpper.position.y = -0.3;
    rightUpper.castShadow = true;
    rightArmGroup.add(rightUpper);
    const rightLower = new THREE.Mesh(new THREE.BoxGeometry(0.18, 0.5, 0.18), skinMat);
    rightLower.position.y = -0.8;
    rightLower.castShadow = true;
    rightArmGroup.add(rightLower);
    humanoid.add(rightArmGroup);

    // Legs (left and right) as groups with upper/lower segments
    // Left leg group
    const leftLegGroup = new THREE.Group();
    leftLegGroup.position.set(-0.25, 0.4, 0);
    const leftUpperLeg = new THREE.Mesh(new THREE.BoxGeometry(0.22, 0.5, 0.22), pantsMat);
    leftUpperLeg.position.y = -0.25;
    leftUpperLeg.castShadow = true;
    leftLegGroup.add(leftUpperLeg);
    const leftLowerLeg = new THREE.Mesh(new THREE.BoxGeometry(0.18, 0.45, 0.18), skinMat);
    leftLowerLeg.position.y = -0.7;
    leftLowerLeg.castShadow = true;
    leftLegGroup.add(leftLowerLeg);
    const leftFoot = new THREE.Mesh(new THREE.BoxGeometry(0.2, 0.15, 0.35), shoeMat);
    leftFoot.position.y = -0.95;
    leftFoot.position.z = 0.1;
    leftFoot.castShadow = true;
    leftLegGroup.add(leftFoot);
    humanoid.add(leftLegGroup);

    // Right leg group
    const rightLegGroup = new THREE.Group();
    rightLegGroup.position.set(0.25, 0.4, 0);
    const rightUpperLeg = new THREE.Mesh(new THREE.BoxGeometry(0.22, 0.5, 0.22), pantsMat);
    rightUpperLeg.position.y = -0.25;
    rightUpperLeg.castShadow = true;
    rightLegGroup.add(rightUpperLeg);
    const rightLowerLeg = new THREE.Mesh(new THREE.BoxGeometry(0.18, 0.45, 0.18), skinMat);
    rightLowerLeg.position.y = -0.7;
    rightLowerLeg.castShadow = true;
    rightLegGroup.add(rightLowerLeg);
    const rightFoot = new THREE.Mesh(new THREE.BoxGeometry(0.2, 0.15, 0.35), shoeMat);
    rightFoot.position.y = -0.95;
    rightFoot.position.z = 0.1;
    rightFoot.castShadow = true;
    rightLegGroup.add(rightFoot);
    humanoid.add(rightLegGroup);

    scene.add(humanoid);

    // --- Animation timing ---
    // Cycle: 0-2s stand, 2-5s walk, 5-8s run, 8-10s stand
    const CYCLE_DURATION = 10;
    let clock = new THREE.Clock();

    // --- Animation parameters ---
    // Walk: arm swing ±0.5 rad, leg swing ±0.35 rad, speed 1.5 Hz (period 0.66s)
    // Run: arm swing ±0.9 rad, leg swing ±0.7 rad, speed 2.5 Hz (period 0.4s)
    // Standing: 0 swing

    function updateHumanoid(time) {
      const t = time % CYCLE_DURATION;
      let phase = 'standing';
      let armAngle = 0;
      let legAngle = 0;
      let lean = 0; // forward lean (rotation.x)

      if (t >= 2 && t < 5) {
        phase = 'walking';
        const local = t - 2;
        const cycle = Math.sin(local * Math.PI * 2 * 1.5); // 1.5 Hz
        armAngle = 0.55 * cycle;
        legAngle = 0.35 * cycle;
        lean = 0.05;
      } else if (t >= 5 && t < 8) {
        phase = 'running';
        const local = t - 5;
        const cycle = Math.sin(local * Math.PI * 2 * 2.5); // 2.5 Hz
        armAngle = 0.95 * cycle;
        legAngle = 0.7 * cycle;
        lean = 0.18;
      } else {
        // standing still
        phase = 'standing';
      }

      // Update phase display
      document.getElementById('phaseDisplay').textContent = phase;

      // Apply lean (forward tilt) to whole humanoid
      humanoid.rotation.x = lean;

      // Arm rotations (opposite phase for left/right)
      leftArmGroup.rotation.z = armAngle; // positive = forward swing
      rightArmGroup.rotation.z = -armAngle;

      // Leg rotations (opposite phase for left/right)
      leftLegGroup.rotation.x = legAngle;
      rightLegGroup.rotation.x = -legAngle;

      // Slight hip bounce for running
      if (phase === 'running') {
        humanoid.position.y = 0.1 * Math.abs(Math.sin((t - 5) * Math.PI * 2 * 2.5));
      } else if (phase === 'walking') {
        humanoid.position.y = 0.04 * Math.abs(Math.sin((t - 2) * Math.PI * 2 * 1.5));
      } else {
        humanoid.position.y = 0;
      }
    }

    // --- Animation loop ---
    function animate() {
      const delta = clock.getDelta();
      const elapsed = clock.elapsedTime;

      updateHumanoid(elapsed);

      // Camera slightly orbits to keep side-on but with a bit of life
      // Actually side-on: keep fixed, but we can add subtle motion
      camera.position.x = 6 + Math.sin(elapsed * 0.2) * 0.3;
      camera.position.y = 4 + Math.sin(elapsed * 0.3) * 0.2;
      camera.lookAt(0, 1.2, 0);

      renderer.render(scene, camera);
      requestAnimationFrame(animate);
    }

    animate();

    // Resize handler
    window.addEventListener('resize', () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
    });

    // --- Add a few floating particles for atmosphere ---
    const particleGeo = new THREE.BoxGeometry(0.1, 0.1, 0.1);
    const particleMat = new THREE.MeshStandardMaterial({ color: 0x88aaff, emissive: 0x224466 });
    for (let i = 0; i < 40; i++) {
      const p = new THREE.Mesh(particleGeo, particleMat);
      p.position.set(
        (Math.random() - 0.5) * 12,
        Math.random() * 4 + 1,
        (Math.random() - 0.5) * 8
      );
      p.scale.set(0.3, 0.3, 0.3);
      scene.add(p);
    }

    // Small floating dust animation
    const dustGroup = new THREE.Group();
    for (let i = 0; i < 20; i++) {
      const d = new THREE.Mesh(new THREE.SphereGeometry(0.05, 4, 4), new THREE.MeshStandardMaterial({ color: 0x6688aa }));
      d.position.set((Math.random() - 0.5) * 6, Math.random() * 2 + 0.5, (Math.random() - 0.5) * 3);
      dustGroup.add(d);
    }
    scene.add(dustGroup);

    // Animate dust in main loop (add to animate)
    const baseAnimate = animate;
    // We'll just add dust movement in the animate function by wrapping
    // but to keep simple, we'll add a small interval
    setInterval(() => {
      dustGroup.children.forEach(d => {
        d.position.y += 0.01;
        if (d.position.y > 3) d.position.y = 0.5;
      });
    }, 100);
  </script>
</body>
</html>
```
